//     CREATE TABLE t1(a, b INTEGER PRIMARY KEY, c);
//     INSERT INTO t1 VALUES(1, 2, 3.1);
//
//   Register (x):        2    (type integer)
//   Register (x+1):      1    (type integer)
//   Register (x+2):      NULL (type NULL)
//   Register (x+3):      3.1  (type real)

